  checkURL2(id: number | string) {

    const found = this.courseVideosSafeUrl.find(e => e.id == +id);

    if (found == undefined) {

      const item = this.course.courseVideos.find(e => e.id == +id);

      if (item == null) {

        return '';
      }

      const video = item.videoUrl.split('/');
      const videoLength = video.length;


      const url = 'https://www.aparat.com/video/video/embed/videohash/' +
        video[videoLength - 1] +
        '/vt/frame';

      const res = this.sanitizer.bypassSecurityTrustResourceUrl(url);

      this.courseVideosSafeUrl.push(new SafeResourceUrlViewModel(+id, res));

      return res;
    } else {
      return found.url;
    }
  }

