  ngOnInit(): void {

    this.siteKey = G.SiteKey;
    GResponse.getCartCoursesCount().subscribe(count => this.courseCount = count);
    GResponse.getCartProductsCount().subscribe(count => this.productCount = count);

    G.getCurrentMode().subscribe(
      res => {
        this.musicColor = res ? '#09964e' : '#09664e';
        this.musicBgColor = res ? '#232323' : '#efefef';
      }
    );

    G.getSettingsDone().subscribe(
      res => {
        this.isLimitShow = G.isOff;
        this.limitDate = G.offDate;
        this.limitTitle = G.limitTitle;

        if (this.isLimitShow) {

          this.timer = setInterval(e => {

            let date1 = new Date(this.limitDate);
            let date2 = new Date();

            let diff = date2.getTime() - date1.getTime();

            if (diff >= 0) {

              this.isLimitShow2 = true;
              clearInterval(this.timer);
            }

            let days = Math.floor(diff / (1000 * 60 * 60 * 24));
            diff -= days * (1000 * 60 * 60 * 24);

            let hours = Math.floor(diff / (1000 * 60 * 60));
            diff -= hours * (1000 * 60 * 60);

            let mins = Math.floor(diff / (1000 * 60));
            diff -= mins * (1000 * 60);

            let seconds = Math.floor(diff / (1000));
            diff -= seconds * (1000);

            if (hours !== 0) {

              hours = 23 - hours;
            }
            if (mins !== 0) {

              mins = 59 - mins;
            }
            if (seconds !== 0) {

              seconds = 60 - seconds;
            }
            if (days < 0) {

              days = -days;
            }
            if (days > 0) {

              days = 1 - days;
            }
            if (days < 0) {

              days = -days;
            }

            let daysShow = '';
            let hoursShow = '';
            let minsShow = '';
            let secondsShow = '';

            if (days === 0) {

              daysShow = '';
            } else {
              daysShow = days.toString() + ':';
            }

            if (hours < 10) {

              hoursShow = '0' + hours.toString();
            } else {
              hoursShow = hours.toString();
            }

            if (mins < 10) {

              minsShow = '0' + mins.toString();
            } else {
              minsShow = mins.toString();
            }

            if (seconds < 10) {

              secondsShow = '0' + seconds.toString();
            } else {
              secondsShow = seconds.toString();
            }

            this.limitDateToString =
              daysShow.toString() + hoursShow.toString() + ':' + minsShow.toString() + ':' + secondsShow.toString();

          }, 1000);
        }
      }
    );

    this.commentForm = this.fb.group({
      comment: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(2000)]],
      private: [false, [Validators.required]]
    });

    this.replyForm = this.fb.group({
      comment: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(2000)]]
    });

    G.getHelpfulLinks().subscribe(
      res => {
        if (res != null) {
          if (res.length > 0) {
            res.forEach(link => {
              this.links.push(link);
            });
          }
        }
      }
    );

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;

    this.activatedRoute.params.subscribe(params => {

      SharedIonic.loading(this.loadingController);

      // tslint:disable-next-line: radix
      const id = parseInt(params.id, 10);

      this.isUserLikedLoading = true;
      this.isBuyLoading = true;

      this.getData(+id);
    });
  }

