  CheckBuy(): boolean {

    if (this.course.price == 0) {
      return false;
    } else {
      return true;
    }
  }

  onBuy() {

    for (let i = 0; i < localStorage.length; i++) {
      if (localStorage.key(i) === 'returnUrl') {
        localStorage.removeItem('returnUrl');
      }
    }

    localStorage.setItem('returnUrl', '/c/' + this.course.id);

    // if (!GAccount.IsLoggedIn()) {

    //   return;
    // }
    SharedIonic.loading(this.loadingController);

    this.orderService.GetUserCart().subscribe(

      res => {

        localStorage.removeItem('returnUrl');

        if (res.status === GResponse.SuccessStatus) {

          if (res.data.courses.find(n => n.id == this.course.id) ? true : false) {

            SharedIonic.dismissLoading(this.loadingController);
            this.router.navigateByUrl(Urls.CartUrl);
            return;
          } else {

            this.orderService.AddCourseById(this.course.id).subscribe(

              // tslint:disable-next-line: no-shadowed-variable
              res2 => {
                if (res2.status === GResponse.SuccessStatus) {

                  GResponse.setCartCoursesCount(++GResponse.BetaCartCoursesCount);

                  // GResponse.CartCoursesCount++;
                  SharedIonic.dismissLoading(this.loadingController);
                  this.router.navigateByUrl(Urls.CartUrl);
                } else {
                  SharedIonic.dismissLoading(this.loadingController);
                  SharedIonic.toast(this.toastController, 'دوره خریداری شده است');
                  location.reload();
                }
              },
              err => {
                SharedIonic.dismissLoading(this.loadingController);
              }
            );
          }
        } else if (res.status === GResponse.NotFoundStatus) {

          this.orderService.AddCourseById(this.course.id).subscribe(

            // tslint:disable-next-line: no-shadowed-variable
            res2 => {
              if (res2.status === GResponse.SuccessStatus) {

                GResponse.setCartCoursesCount(++GResponse.BetaCartCoursesCount);

                // GResponse.CartCoursesCount++;
                SharedIonic.dismissLoading(this.loadingController);
                this.router.navigateByUrl(Urls.CartUrl);
              } else {
                SharedIonic.dismissLoading(this.loadingController);
                SharedIonic.toast(this.toastController, 'دوره خریداری شده است');
                location.reload();
              }
            },
            err => {
              SharedIonic.dismissLoading(this.loadingController);
            }
          );
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  getTeacherName() {

    if (this.course.teacherUser == undefined || this.course.teacherUser == null) {

      return '';
    }
    const name = this.course.teacherUser.name != null ? this.course.teacherUser.name : '';
    const family = this.course.teacherUser.family != null ? this.course.teacherUser.family : '';

    return name + ' ' + family;
  }

  OnLike(like: boolean) {

    if (GAccount.IsLoggedIn() && GAccount.IsBuyer()) {

      this.isLikeLoadingShow = true;

      this.courseService.AddOrUpdateUserLikedCourse(this.course.id, like).subscribe(
        res => {
          this.isLikeLoadingShow = false;
          if (res.status === GResponse.SuccessStatus) {
            this.course.userLiked = like;
          }
        },
        err => {
          this.isLikeLoadingShow = false;
        }
      );
    }
  }

  isLikeShow(): boolean {

    return GAccount.IsLoggedIn();
  }

